values ('petroleum-distribution', 'Petroleum Distribution Management System', 'Freelance Software Engineer — Frontend Development & Client Coordination', 'An enterprise petroleum distribution platform supporting wholesale, retail, logistics, and master data operations. Responsible for frontend development, client communication, requirements analysis, and UI/UX prototyping, while collaborating with a dedicated backend development team.', null, 'general', array['Frontend Engineering', 'UI/UX Prototyping', 'API Integration', 'Business Analysis', 'Client Collaboration']::text[], 'A business platform supporting petroleum distribution operations, covering wholesale, retail, logistics, and master data.', 'Distribution operations involve several connected business areas. Each workflow needs to reflect real operational rules while staying consistent with shared master data.', 'Responsible for frontend implementation using Next.js, React, and TypeScript, communicating directly with clients to understand business requirements, creating Figma prototypes, and coordinating with backend developers to deliver integrated business workflows.', 'The Laravel backend, including its APIs and database, is implemented and maintained by a dedicated backend team.', 'Requirements are clarified with the client and prototyped in Figma before implementation. The Next.js frontend consumes REST APIs from the Laravel backend built by the backend team, with API contracts and business rules agreed together before integration.', 'Close collaboration with stakeholders and early prototyping help align complex operational workflows before code is written.', array['Next.js', 'React', 'TypeScript', 'Figma', 'REST APIs']::text[], array['Next.js', 'React', 'TypeScript', 'Figma', 'REST APIs', 'Laravel (backend team)']::text[], array['Developed frontend features using Next.js, React, and TypeScript.', 'Communicated with clients to gather and clarify business requirements.', 'Created Figma prototypes and translated requirements into working interfaces.', 'Integrated frontend modules with REST APIs.', 'Coordinated with backend developers on API contracts and business rules.', 'Contributed to wholesale, retail, logistics, and master data workflows.']::text[], null, 'published', 0)
on conflict (slug) do nothing;
values ('general-core-insurance', 'General Core Insurance Platform', 'Frontend Team Leader', 'An enterprise general insurance platform where I led frontend development and contributed hands-on to implementing core insurance workflows using Angular, while coordinating technical requirements with backend teams and clients.', null, 'general', array['Frontend Engineering', 'Enterprise Applications', 'API Integration', 'Technical Leadership', 'Business Workflows']::text[], 'An enterprise general insurance system covering the core insurance lifecycle, from underwriting requests and quotations to policies, claims, and endorsements.', 'Insurance workflows are rule-heavy and interconnected. The frontend needed to represent these processes clearly while staying aligned with backend services built by a separate team.', 'Frontend Team Leader: implemented Angular features directly while guiding the frontend team and coordinating requirements with backend developers and clients. ', 'Backend services were built and owned by a separate backend team.', 'Shared, reusable Angular components were used across modules, with each workflow integrated against backend REST APIs.', 'Reusable components and clear communication between frontend, backend, and clients are essential in large, rule-heavy business domains.', array['Angular', 'TypeScript', 'REST APIs']::text[], array['Angular', 'TypeScript', 'REST APIs']::text[], array['Hands-on Angular frontend development.', 'Insurance modules and business workflows.', 'Underwriting requests.', 'Quotations.', 'Policy management.', 'Claims.', 'Endorsements.', 'Reusable frontend components.', 'REST API integration.', 'Frontend team leadership.', 'Backend requirements coordination.', 'Client communication and support.']::text[], null, 'published', 1)
